def _register_namespaces_from_bytes(xml_bytes: bytes) -> dict[str, str]:
    """Register namespaces found in the source XML.

    ElementTree does not preserve original prefix mappings unless we register
    them prior to serialization. We harvest (prefix, uri) pairs via iterparse
    'start-ns' events.
    """
    ns_map: dict[str, str] = {}
    for _event, (prefix, uri) in ET.iterparse(io.BytesIO(xml_bytes), events=("start-ns",)):
        # Keep the first mapping we see for a given prefix.
        if prefix in ns_map:
            continue
        ns_map[prefix] = uri
        ET.register_namespace(prefix, uri)
    return ns_map

